using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class FieldDuplicateIntKeyTests
{
    private readonly ITestOutputHelper logger;

    public FieldDuplicateIntKeyTests(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    private static async Task<CSharpCompilation> CreateCompilationAsync(string source)
    {
        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> refs = new List<MetadataReference>(frameworkRefs);
        foreach (var r in ReferencesHelper.GetReferences(ReferencesSet.MessagePack))
        {
            refs.Add(r);
        }

        return CSharpCompilation.Create(
            "ReceiptsTestAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
    }

    private static ImmutableArray<DiagnosticAnalyzer> GetAnalyzers()
    {
        return typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly.GetTypes()
            .Where(t => !t.IsAbstract && typeof(DiagnosticAnalyzer).IsAssignableFrom(t) && t.GetConstructor(Type.EmptyTypes) is not null)
            .Select(t => (DiagnosticAnalyzer)Activator.CreateInstance(t)!)
            .ToImmutableArray();
    }

    private async Task AssertNoAnalyzerCrashAsync(string source)
    {
        CSharpCompilation compilation = await CreateCompilationAsync(source);
        ImmutableArray<DiagnosticAnalyzer> analyzers = GetAnalyzers();
        Assert.NotEmpty(analyzers);
        ImmutableArray<Diagnostic> diagnostics = await compilation.WithAnalyzers(analyzers).GetAnalyzerDiagnosticsAsync();
        foreach (Diagnostic d in diagnostics)
        {
            this.logger.WriteLine(d.ToString());
        }

        Assert.DoesNotContain(diagnostics, d => d.Id == "AD0001");
    }

    [Fact]
    public async Task AnalyzerDoesNotThrow_DuplicateIntKeyFields_Suppressed()
    {
        string source = """
            using MessagePack;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class DupFields
            {
                [Key(0)]
                public int A;

                [Key(0)]
                public int B;
            }
            """;
        await this.AssertNoAnalyzerCrashAsync(source);
    }

    [Fact]
    public async Task AnalyzerDoesNotThrow_PropertyAndFieldSameIntKey_Suppressed()
    {
        string source = """
            using MessagePack;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class DupPropField
            {
                [Key(0)]
                public int P { get; set; }

                [Key(0)]
                public int F;
            }
            """;
        await this.AssertNoAnalyzerCrashAsync(source);
    }

    [Fact]
    public async Task GeneratorDoesNotThrow_DuplicateIntKeyFields()
    {
        string source = """
            using MessagePack;

            [MessagePackObject]
            public class DupFields2
            {
                [Key(0)]
                public int A;

                [Key(0)]
                public int B;
            }
            """;
        CSharpCompilation compilation = await CreateCompilationAsync(source);
        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGenerators(compilation);
        GeneratorDriverRunResult result = driver.GetRunResult();
        foreach (Diagnostic d in result.Diagnostics)
        {
            this.logger.WriteLine(d.ToString());
        }

        Assert.All(result.Results, r => Assert.Null(r.Exception));
        Assert.DoesNotContain(result.Diagnostics, d => d.Id == "CS8785");
    }
}
